// Lo que sabemos de Muebles Roble. Lo medido sale de la Clase 8.
// SUPUESTO = un dato que hay que confirmar con el cliente en la Fase 0 (auditoría y línea de base).
return [{ json: {
  cliente: 'Muebles Roble',
  decide: 'Marta Ríos (dueña) y su contador',
  proceso: 'Atención de consultas repetidas y presupuestos de compradores grandes',

  // Línea de base: cómo se trabaja hoy, sin el sistema (caso.md)
  consultas_por_dia: 60,
  porcentaje_repetidas: 0.7,        // 7 de cada 10 son las mismas preguntas
  dias_habiles_mes: 22,
  horas_julian_por_dia: 3,          // lo que Julián dedica a esas consultas
  costo_hora_julian_usd: 6,         // SUPUESTO
  presupuestos_perdidos_mes: 2,     // Marta calcula que pierde 2 o 3 por mes
  ticket_presupuesto_usd: 1500,     // SUPUESTO: un presupuesto grande promedio
  margen_bruto: 0.3,                // SUPUESTO: lo que le queda a Roble de cada venta

  // Medición de la Clase 8 (arquitectura B)
  precision_medida: 0.8,            // 4 de 5 casos de oro correctos
  hitl_rate: 0.2,                   // 1 de cada 5 consultas la revisa una persona
  costo_1000_consultas_usd: 0.5,    // tokens reales de Groq
  plataforma_mes_usd: 24,           // n8n
} }];

// El código hace todas las cuentas. Dos escenarios: el conservador va primero.
const d = $input.first().json;
const consultas_mes = Math.round(d.consultas_por_dia * d.porcentaje_repetidas * d.dias_habiles_mes);
const ahorro_horas = d.horas_julian_por_dia * d.dias_habiles_mes * d.costo_hora_julian_usd * (1 - d.hitl_rate);
const costo_tokens = consultas_mes * d.costo_1000_consultas_usd / 1000;
const costo_fijo = d.plataforma_mes_usd + costo_tokens + d.soporte_mes_usd;
const recuperados = d.presupuestos_perdidos_mes * d.recupero_esperado;
const margen_recuperado = recuperados * d.ticket_presupuesto_usd * d.margen_bruto;
const exito_usd = recuperados * d.ticket_presupuesto_usd * d.exito_porcentaje;
const r = x => Math.round(x * 100) / 100;
function escenario(nombre, beneficio, costo, cobro_exito) {
  const neto = beneficio - costo;
  return {
    nombre,
    beneficio_mes_usd: Math.round(beneficio),
    costo_mes_usd: Math.round(costo),
    neto_mes_usd: Math.round(neto),
    payback_meses: neto > 0 ? (d.implementacion_usd / neto).toFixed(1).replace('.', ',') : 'no se paga',
    roi_12_meses: Math.round((neto * 12 - d.implementacion_usd) / d.implementacion_usd * 100) + '%',
    ingreso_consultor_ano_usd: Math.round(d.implementacion_usd + 12 * (d.soporte_mes_usd + cobro_exito)),
  };
}
return [{ json: {
  ...d,
  consultas_mes,
  ahorro_horas_mes_usd: Math.round(ahorro_horas),
  costo_tokens_mes_usd: r(costo_tokens),
  presupuestos_recuperados_mes: recuperados,
  margen_recuperado_mes_usd: Math.round(margen_recuperado),
  exito_mes_usd: Math.round(exito_usd),
  conservador: escenario('Conservador: solo el tiempo de Julián, sin presupuestos recuperados',
                         ahorro_horas, costo_fijo, 0),
  esperado: escenario('Esperado: además se recupera la mitad de los presupuestos que hoy se pierden',
                      ahorro_horas + margen_recuperado, costo_fijo + exito_usd, exito_usd),
} }];

// La IA redacta; el código revisa. Busca palabras técnicas que el comité no entiende.
const JERGA = new RegExp("\\b(n8n|nodos?|workflows?|sub-?workflows?|LLM|modelos? de lenguaje|embeddings?|tokens?|prompts?|RAG|API|webhooks?|JSON|Groq|vectorial(es)?|traceId|AI-as-a-Judge|Human-in-the-loop|HITL|Manager-Worker|machine learning|inteligencia artificial generativa)\\b", 'gi');
const prep = $('Preparar intento').first().json;
const g = $input.first().json;
const n = JSON.parse(g.choices[0].message.content);
const textos = [n.titulo, n.problema, n.promesa,
  ...n.funcion_beneficio.map(f => f.en_simple + ' ' + f.beneficio),...n.objeciones.map(o => o.respuesta)].join(' ');
const jerga = [...new Set((textos.match(JERGA) || []).map(p => p.toLowerCase()))];
return [{ json: {
  ...prep,
  narrativa: n,
  jerga,
  tokens_redaccion: (prep.tokens_redaccion || 0) + g.usage.total_tokens,
} }];

// Arma el brochure de cuatro secciones (las del material). Lo fijo lo escribe el consultor; la narrativa, la IA.
const d = $input.first().json;
const n = d.narrativa;
const ROADMAP = [
  {
    "fase": "Fase 0 · Modo sombra",
    "cuando": "Semanas 1 y 2",
    "puede": "Leer las consultas y proponer respuestas que no le llegan al cliente",
    "prohibido": "Responder al cliente y registrar datos en HubSpot",
    "valida": "Julián, una por una",
    "salida": "50 consultas reales con 90% de respuestas correctas según Julián y ninguna promesa fuera del manual"
  },
  {
    "fase": "Fase 1 · Piloto de solo lectura",
    "cuando": "Semanas 3 a 6",
    "puede": "Responder las preguntas frecuentes (envíos, cuotas, garantía) con el manual",
    "prohibido": "Registrar o cambiar datos, y prometer reembolsos o descuentos",
    "valida": "El revisor, en cada respuesta; Julián, una muestra por semana",
    "salida": "4 semanas con menos del 20% de consultas derivadas a una persona y sin errores graves"
  },
  {
    "fase": "Fase 2 · Escritura controlada",
    "cuando": "Semanas 7 a 10",
    "puede": "Registrar presupuestos grandes en HubSpot y preparar respuestas a reclamos",
    "prohibido": "Hacerlo sin la aprobación de una persona del equipo por Telegram",
    "valida": "El equipo, en cada acción",
    "salida": "95% de aprobaciones sin cambios durante 4 semanas"
  },
  {
    "fase": "Fase 3 · Autonomía supervisada",
    "cuando": "Desde la semana 11",
    "puede": "Registrar presupuestos sin aprobación previa, dentro de las reglas",
    "prohibido": "Reembolsos, descuentos y reclamos legales: siempre los decide una persona",
    "valida": "El revisor, en cada respuesta; informe mensual a Marta",
    "salida": "Si la precisión baja del 90%, se vuelve a la Fase 2"
  }
];
const PLAN = [
  {
    "cuando": "Días 1 a 5",
    "hito": "Auditoría del proceso: medir consultas, horas y presupuestos perdidos (la línea de base)",
    "responsable": "Consultor, con Julián"
  },
  {
    "cuando": "Días 6 a 10",
    "hito": "Configuración: manual de políticas, revisor y reglas de qué decide una persona",
    "responsable": "Consultor"
  },
  {
    "cuando": "Días 11 a 20",
    "hito": "Fase 0, modo sombra: 50 consultas reales revisadas",
    "responsable": "Julián"
  },
  {
    "cuando": "Días 21 a 25",
    "hito": "Informe de la medición y decisión de pasar a la Fase 1",
    "responsable": "Marta, con el consultor"
  },
  {
    "cuando": "Días 26 a 30",
    "hito": "Fase 1, piloto de solo lectura en el chat de la tienda",
    "responsable": "Consultor (seguimiento diario)"
  }
];
const FALLBACK = "Si el asistente no responde en 30 segundos o el proveedor falla, el cliente recibe \"Tu consulta la revisa una persona del equipo\" y la consulta le llega a Julián por Telegram. Ninguna consulta se pierde ni se responde dos veces.";
const TRAZABILIDAD = "Cada conversación lleva un número de seguimiento. Cuando el asistente registra un presupuesto en HubSpot, completa dos campos: Origen = Asistente y el número de seguimiento. El cobro por resultado se calcula solo con esos registros: son la única fuente de verdad, para Roble y para el consultor.";
const DIAGRAMA = "flowchart LR\n    C[Clientes: chat, correo y Telegram] --> R[Coordinador: entiende qué necesita cada cliente]\n    R --> V[Especialista en ventas]\n    R --> P[Especialista en postventa]\n    V --> Q[Revisor de calidad]\n    P --> Q\n    M[(Manual de políticas)] --> V\n    M --> P\n    Q -- correcta --> C\n    Q -- riesgo o duda --> E[Equipo de Roble: aprueba por Telegram]\n    V --> H[(HubSpot: presupuestos grandes)]";
const e = t => String(t).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const usd = x => 'US$ ' + Number(x).toLocaleString('es-AR');
const tabla = (cab, filas) => '<table><tr>' + cab.map(c => '<th>' + e(c) + '</th>').join('') + '</tr>'
  + filas.map(f => '<tr>' + f.map(c => '<td>' + e(c) + '</td>').join('') + '</tr>').join('') + '</table>';
const esc = [d.conservador, d.esperado];
const html = `<!doctype html><html lang="es"><head><meta charset="utf-8">
<title>${e(n.titulo)}</title>
<style>
body{font-family:Arial,Helvetica,sans-serif;color:#1a1a1a;max-width:860px;margin:32px auto;padding:0 24px;line-height:1.5}
h1{font-size:28px;margin-bottom:4px}h2{border-bottom:3px solid #ff632b;padding-bottom:4px;margin-top:36px}
table{border-collapse:collapse;width:100%;margin:12px 0;font-size:14px}th,td{border:1px solid #ccc;padding:6px 8px;text-align:left;vertical-align:top}
th{background:#ffe5db}.sub{color:#555}.nota{background:#f6f6f6;padding:10px 14px;border-left:4px solid #ff632b}
@media print{h2{break-before:auto}table,tr{break-inside:avoid}}
</style></head><body>
<h1>${e(n.titulo)}</h1>
<p class="sub">Propuesta para ${e(d.decide)} · ${e(d.cliente)}</p>
<h2>1. El problema y la promesa</h2>
<p><strong>Hoy.</strong> ${e(n.problema)}</p>
<p><strong>Con el sistema.</strong> ${e(n.promesa)}</p>
<h3>Cómo funciona</h3>
<pre class="mermaid">${DIAGRAMA}</pre>
<h3>Qué gana el negocio</h3>
${tabla(['Lo que hace el sistema', 'Lo que gana Roble'], n.funcion_beneficio.map(f => [f.en_simple, f.beneficio]))}
<h3>Los números</h3>
<p>Línea de base: ${d.consultas_mes} consultas repetidas por mes, ${d.horas_julian_por_dia} horas por día de Julián y ${d.presupuestos_perdidos_mes} presupuestos grandes perdidos por mes. Precisión medida en las pruebas: ${Math.round(d.precision_medida * 100)}%.</p>
${tabla(['Escenario', 'Beneficio por mes', 'Costo por mes', 'Neto por mes', 'Se paga en', 'ROI a 12 meses'],
  esc.map(s => [s.nombre, usd(s.beneficio_mes_usd), usd(s.costo_mes_usd), usd(s.neto_mes_usd), s.payback_meses + ' meses', s.roi_12_meses]))}
<h2>2. El despliegue, por fases</h2>
${tabla(['Fase', 'Cuándo', 'Qué puede hacer', 'Qué tiene prohibido', 'Quién valida', 'Para pasar a la siguiente'],
  ROADMAP.map(f => [f.fase, f.cuando, f.puede, f.prohibido, f.valida, f.salida]))}
<p class="nota"><strong>Si algo falla.</strong> ${e(FALLBACK)}</p>
<h2>3. Cómo se cobra</h2>
${tabla(['Componente', 'Monto', 'Qué incluye'], [
  ['Implementación (una vez)', usd(d.implementacion_usd), d.implementacion_incluye],
  ['Soporte mensual', usd(d.soporte_mes_usd) + ' por mes', d.soporte_incluye.join('. ') + '.'],
  ['Por resultado', Math.round(d.exito_porcentaje * 100) + '% de cada venta', d.kpi + ', dentro de los ' + d.ventana_dias + ' días desde que el sistema lo registró'],
])}
<p>Si el sistema no recupera ningún presupuesto, Roble no paga la parte por resultado: ese riesgo lo asume el consultor.</p>
<h2>4. Los primeros 30 días</h2>
${tabla(['Cuándo', 'Hito', 'Responsable'], PLAN.map(p => [p.cuando, p.hito, p.responsable]))}
<p class="nota"><strong>Cómo se mide el resultado.</strong> ${e(TRAZABILIDAD)}</p>
<h3>Preguntas del comité</h3>
${tabla(['Pregunta', 'Respuesta'], n.objeciones.map(o => [o.objecion, o.respuesta]))}
<script src="https://cdn.jsdelivr.net/npm/mermaid@11.4.1/dist/mermaid.min.js"></script>
<script>mermaid.initialize({ startOnLoad: true, theme: 'neutral' });</script>
</body></html>`;
return [{ json: {
  titulo: n.titulo,
  payback_conservador: d.conservador.payback_meses + ' meses',
  payback_esperado: d.esperado.payback_meses + ' meses',
  intentos: d.intento,
  jerga_que_quedo: d.jerga.join(', '),
  tokens_redaccion: d.tokens_redaccion,
  brochure_html: html,
} }];
